import React, { useEffect, useState } from "react";
import Navbar from "../Components/Navbar";
import Footer from "../Components/Footer";
import API_BASE_URL from "../config";
import "../App.css";

const RateUser = () => {
  const [usersToRate, setUsersToRate] = useState([]);
  const userId = sessionStorage.getItem("userId");

  useEffect(() => {
    if (userId) {
      fetch(`${API_BASE_URL}/api/ratings/partners/${userId}`)
        .then((res) => res.json())
        .then((data) => {
          if (Array.isArray(data)) {
            setUsersToRate(data);
          } else {
            setUsersToRate([]);
          }
        })
        .catch((err) => {
          console.error("Failed to load users to rate:", err);
          setUsersToRate([]);
        });
    }
  }, [userId]);

  const handleRate = async (ratedUserId, rating) => {
    const res = await fetch(`${API_BASE_URL}/api/ratings`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        rater_id: userId,
        rated_id: ratedUserId,
        rating,
      }),
    });

    if (res.ok) {
      alert("Rating submitted!");
      // Remove user from list after rating
      setUsersToRate((prev) => prev.filter((u) => u.id !== ratedUserId));
    } else {
      alert("Failed to submit rating.");
    }
  };

  return (
    <div className="dashboard-wrapper" style={{ minHeight: "100vh", display: "flex", flexDirection: "column" }}>
      <Navbar />
      <main className="dashboard-main" style={{ flex: 1, padding: "32px 48px" }}>
        <h2 style={{ textAlign: "center", marginBottom: "24px" }}>Rate Other Users</h2>

        {usersToRate.length === 0 ? (
          <p style={{ textAlign: "center" }}>No users to rate yet.</p>
        ) : (
          <div className="user-grid">
            {usersToRate.map((user) => (
              <div key={user.id} className="rate-card">
                <h4>{user.username}</h4>
                <p>{user.email}</p>
                <div className="rating-buttons">
                  {[1, 2, 3, 4, 5].map((n) => (
                    <button key={n} onClick={() => handleRate(user.id, n)} className="rate-btn">
                      {n}⭐
                    </button>
                  ))}
                </div>
              </div>
            ))}
          </div>
        )}
      </main>
      <Footer />
    </div>
  );
};

export default RateUser;
